record.field:
{
    "properties": {
        "limit": {
            "type": "number",
            "description": "Maximum number of sale orders to return (default: 10)"
        }
    },
    "required": [],
    "type": "object"
}

{
    "properties": {
        "category_id": {
            "type": "number",
            "description": "Product category ID to filter by (optional – omit for all products)"
        }
    },
    "required": [],
    "type": "object"
}

{
    "properties": {
        "partner_id": {
            "type": "number",
            "description": "ID of the customer (partner) for the quotation"
        },
        "lines": {
            "type": "array",
            "description": "List of order lines",
            "items": {
                "type": "object",
                "properties": {
                    "product_id": {
                        "type": "number",
                        "description": "ID of the product"
                    },
                    "qty": {
                        "type": "number",
                        "description": "Quantity to order"
                    },
                    "price_unit": {
                        "type": "number",
                        "description": "Unit price (optional, uses product list price if omitted)"
                    }
                },
                "required": ["product_id", "qty"]
            }
        },
        "note": {
            "type": "string",
            "description": "Optional terms, notes, or remarks for the quotation"
        }
    },
    "required": ["partner_id", "lines"],
    "type": "object"
}
